import { Component, computed, DestroyRef, inject, OnInit, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { forkJoin } from 'rxjs';
import { CoordenadasPickerComponent, CoordenadasValue } from '../../../../shared/components/coordenadas-picker/coordenadas-picker.component';
import { DocumentUploaderComponent } from '../../../../shared/components/document-uploader/document-uploader';
import { PdfViewerComponent } from '../../../../shared/components/pdf-viewer/pdf-viewer.component';
import { ToastContainerComponent } from '../../../../shared/components/toast-container/toast-container.component';
import { TramiteProgressBarComponent } from '../../../../shared/components/tramite-progress-bar/tramite-progress-bar.component';
import { ToastService } from '../../../../shared/services/toast.service';
import { DocumentoService } from '../../../../services/documento.service';
import { SolicitudPayload, SolicitudService } from '../../../../shared/services/solicitud.service';
import { TramiteService } from '../../../../shared/services/tramite.service';
import { TramiteDatosSolicitud } from '../../../../shared/models/solicitud.model';
import { extractErrorMessage } from '../../../../shared/utils/error-utils';
import {
  createInitialTramiteSolicitudData,
  TramiteCatalogoItem,
  TramitePestana,
  TramiteRequisitoItem,
  TramiteSolicitudData,
} from '../../../../shared/models/tramite-catalogo.model';
import { Municipio, MunicipioFiltro } from '../../../../shared/models/municipio.model';
import { crearPdfDemo, createDemoTramiteSolicitudData } from './tramite-solicitud-demo-data';

@Component({
  selector: 'app-tramite-solicitud',
  imports: [
    CommonModule,
    FormsModule,
    CoordenadasPickerComponent,
    DocumentUploaderComponent,
    PdfViewerComponent,
    ToastContainerComponent,
    TramiteProgressBarComponent,
  ],
  templateUrl: './tramite-solicitud.component.html',
  styleUrl: './tramite-solicitud.component.scss',
  host: {
    '(document:keydown)': 'onSecretKey($event)',
  },
})
export class TramiteSolicitudComponent implements OnInit {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly toast = inject(ToastService);
  private readonly documentoService = inject(DocumentoService);
  private readonly tramiteService = inject(TramiteService);

  /** Easter egg para el botón de auto-llenar */
  readonly demoUnlocked = signal(false);
  private secretBuffer = '';
  private readonly solicitudService = inject(SolicitudService);
  private readonly destroyRef = inject(DestroyRef);
  readonly catalogo = signal<TramiteCatalogoItem[]>([]);
  readonly municipios = signal<Municipio[]>([]);
  readonly isLoadingCatalogo = signal<boolean>(true);
  readonly catalogoError = signal<string | null>(null);
  private readonly tramiteIdQuery = signal<string | null>(null);
  readonly selectedMunicipio = signal<MunicipioFiltro>('todos');
  readonly selectedTramite = signal<TramiteCatalogoItem | null>(null);
  readonly currentStepIndex = signal<number>(0);
  readonly submitFolio = signal<string | null>(null);
  readonly submitSuccess = signal<boolean>(false);
  readonly isSubmitting = signal<boolean>(false);
  readonly submitError = signal<string | null>(null);
  readonly mostrarVisor = signal<boolean>(false);
  readonly selectedDocId = signal<number | null>(null);
  readonly selectedDocUrl = signal<string | null>(null);
  readonly selectedDocNombre = signal<string | null>(null);

  readonly formData = signal<TramiteSolicitudData>(
    createInitialTramiteSolicitudData('', null, '')
  );

  /** Documentos adjuntos indexados por requisito (derivado, sin funciones en el template). */
  readonly documentosAdjuntos = computed(() => this.formData().documentosAdjuntos);

  readonly tramitesPorMunicipio = computed(() => {
    const mun = this.selectedMunicipio();
    return this.catalogo().filter((t) => this.matchesMunicipio(t, mun));
  });

  readonly pestanasActivas = computed<TramitePestana[]>(() => {
    const tramite = this.selectedTramite();
    if (!tramite) {
      return [{ id: 'seleccion', titulo: 'Selección de Trámite', icono: 'bi-check2-square' }];
    }
    return [
      { id: 'seleccion', titulo: 'Trámite y Municipio', icono: 'bi-bank' },
      ...tramite.pestanas,
    ];
  });

  readonly currentPestana = computed<TramitePestana | null>(() => {
    const steps = this.pestanasActivas();
    const idx = this.currentStepIndex();
    return steps[idx] ?? null;
  });

  readonly esResiduosManejoEspecial = computed<boolean>(() => {
    const tramite = this.selectedTramite();
    return tramite?.claveOficial === 'SMADS-RME' || tramite?.id === 'bc-plan-residuos';
  });

  readonly claveCatastralObligatoria = computed<boolean>(
    () => this.selectedTramite()?.nivelGobierno === 'municipal',
  );

  /** Requisito correspondiente al comprobante de pago */
  readonly requisitoPago = computed<TramiteRequisitoItem | null>(() => {
    const requisitos = this.selectedTramite()?.requisitos ?? [];
    return (
      requisitos.find((r) => r.id.endsWith('_pago') || r.id.includes('pago')) ?? null
    );
  });

  /** Requisitos oficiales excluyendo el pago, para la pestaña de Documentación Oficial */
  readonly requisitosDocumentos = computed<TramiteRequisitoItem[]>(() => {
    const pagoId = this.requisitoPago()?.id;
    const requisitos = this.selectedTramite()?.requisitos ?? [];
    if (!pagoId) return requisitos;
    return requisitos.filter((r) => r.id !== pagoId);
  });

  ngOnInit(): void {
    this.route.queryParams
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe((params) => {
        this.tramiteIdQuery.set((params['tramiteId'] as string | undefined) ?? null);
        this.aplicarTramiteDesdeQuery();
      });

    forkJoin({
      tramites: this.tramiteService.getCatalogo(),
      municipios: this.solicitudService.getMunicipios(),
    })
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: ({ tramites, municipios }) => {
          this.catalogo.set(tramites);
          this.municipios.set(municipios);
          this.isLoadingCatalogo.set(false);
          this.aplicarTramiteDesdeQuery();
        },
        error: (err) => {
          this.isLoadingCatalogo.set(false);
          this.catalogoError.set(extractErrorMessage(err));
        },
      });
  }

  private aplicarTramiteDesdeQuery(): void {
    const tramiteId = this.tramiteIdQuery();
    if (!tramiteId) return;
    const found = this.catalogo().find((t) => t.id === tramiteId);
    if (found && this.selectedTramite()?.id !== found.id) {
      this.seleccionarTramite(found);
      this.currentStepIndex.set(1);
    }
  }

  onMunicipioChange(municipio: MunicipioFiltro): void {
    this.selectedMunicipio.set(municipio);
    const disponibles = this.tramitesPorMunicipio();
    if (this.selectedTramite() && !disponibles.some((t) => t.id === this.selectedTramite()?.id)) {
      this.selectedTramite.set(null);
      this.currentStepIndex.set(0);
    }
  }

  private matchesMunicipio(tramite: TramiteCatalogoItem, filtro: MunicipioFiltro): boolean {
    if (filtro === 'todos') return true;
    if (filtro === 'estatal') return tramite.municipioId === null || tramite.nivelGobierno === 'estatal';
    if (tramite.municipioId === filtro) return true;
    return tramite.municipioNombre === this.municipios().find((m) => m.id === filtro)?.nombre;
  }

  onCampoChange<K extends keyof TramiteSolicitudData>(campo: K, value: TramiteSolicitudData[K]): void {
    this.formData.update((data) => ({ ...data, [campo]: value }));
  }

  setPersonalidad(personalidad: 'fisica' | 'moral'): void {
    this.formData.update((data) => ({ ...data, personalidad }));
  }

  seleccionarTramite(tramite: TramiteCatalogoItem): void {
    this.selectedTramite.set(tramite);
    this.formData.set(
      createInitialTramiteSolicitudData(tramite.id, tramite.municipioId, tramite.municipioNombre)
    );
  }

  cambiarTramite(): void {
    this.currentStepIndex.set(0);
  }

  autollenarDemo(): void {
    const tramite = this.selectedTramite();
    if (!tramite) return;

    this.formData.set(createDemoTramiteSolicitudData(tramite));

    const obligatorios = tramite.requisitos.filter((r) => r.obligatorio);
    if (obligatorios.length === 0) {
      this.toast.success(`${tramite.claveOficial} autollenado con datos de demostración`);
      return;
    }

    const demoFile = crearPdfDemo(`${tramite.claveOficial}-demo.pdf`);
    forkJoin(obligatorios.map(() => this.documentoService.uploadDocumento(demoFile)))
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: (resultados) => {
          this.formData.update((data) => {
            const docs = { ...data.documentosAdjuntos };
            obligatorios.forEach((req, i) => {
              docs[req.id] = { file: demoFile, id: resultados[i].id, name: req.nombre };
            });
            return { ...data, documentosAdjuntos: docs };
          });
          this.toast.success(`${tramite.claveOficial} autollenado con datos y documentos de demostración`);
        },
        error: () => {
          this.toast.warning(
            'Datos autollenados, pero no se pudieron subir los documentos de demostración. Súbelos manualmente.',
          );
        },
      });
  }

  private camposObligatoriosCompletados(): boolean[] {
    const data = this.formData();
    const checks: boolean[] = [!!data.rfc, !!data.correo, !!data.telefono];
    if (data.personalidad === 'moral') {
      checks.push(!!data.razonSocial, !!data.representanteLegal);
    } else {
      checks.push(!!data.nombreSolicitante);
    }
    checks.push(!!data.calle, !!data.numeroExterior, !!data.colonia);
    if (this.claveCatastralObligatoria()) {
      checks.push(!!data.claveCatastral);
    }
    return checks;
  }

  private documentosObligatorios(): TramiteRequisitoItem[] {
    return (this.selectedTramite()?.requisitos ?? []).filter((r) => r.obligatorio);
  }

  readonly progressTotal = computed<number>(
    () => this.camposObligatoriosCompletados().length + this.documentosObligatorios().length,
  );

  readonly progressCompleted = computed<number>(() => {
    const campos = this.camposObligatoriosCompletados().filter(Boolean).length;
    const docs = this.formData().documentosAdjuntos;
    const documentos = this.documentosObligatorios().filter((req) => {
      const doc = docs[req.id];
      return !!doc?.file && doc.id !== null && doc.id !== undefined;
    }).length;
    return campos + documentos;
  });

  onSecretKey(event: KeyboardEvent): void {
    if (this.demoUnlocked()) return;
    const target = event.target as HTMLElement | null;
    if (
      target &&
      (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.tagName === 'SELECT' || target.isContentEditable)
    ) {
      return;
    }
    if (event.key.length !== 1) return;
    this.secretBuffer = (this.secretBuffer + event.key.toLowerCase()).slice(-4);
    if (this.secretBuffer === 'demo') {
      this.secretBuffer = '';
      this.demoUnlocked.set(true);
      this.toast.info('Modo demo desbloqueado');
    }
  }

  goToStep(index: number): void {
    if (index >= 0 && index < this.pestanasActivas().length) {
      this.currentStepIndex.set(index);
    }
  }

  nextStep(): void {
    if (this.currentStepIndex() < this.pestanasActivas().length - 1) {
      this.currentStepIndex.update((i) => i + 1);
    }
  }

  prevStep(): void {
    if (this.currentStepIndex() > 0) {
      this.currentStepIndex.update((i) => i - 1);
    }
  }

  onCoordenadasChange(coords: CoordenadasValue): void {
    this.formData.update((data) => ({
      ...data,
      latitud: coords.latitud,
      longitud: coords.longitud,
      altitud: coords.altitud,
    }));
  }

  onDocumentoChange(requisitoId: string, requisitoNombre: string, file: File | null): void {
    this.formData.update((data) => {
      const docs = { ...data.documentosAdjuntos };
      if (file) {
        docs[requisitoId] = {
          file,
          id: docs[requisitoId]?.id ?? null,
          name: requisitoNombre,
        };
      } else {
        delete docs[requisitoId];
      }
      return { ...data, documentosAdjuntos: docs };
    });
  }

  onDocumentoIdChange(requisitoId: string, documentoId: number | null): void {
    this.formData.update((data) => {
      const actual = data.documentosAdjuntos[requisitoId];
      if (!actual) return data;
      return {
        ...data,
        documentosAdjuntos: {
          ...data.documentosAdjuntos,
          [requisitoId]: { ...actual, id: documentoId },
        },
      };
    });
  }

  isSolicitanteStepValid(): boolean {
    const data = this.formData();
    const basicValid = !!data.rfc && !!data.correo && !!data.telefono;
    if (data.personalidad === 'moral') {
      return basicValid && !!data.razonSocial && !!data.representanteLegal;
    }
    return basicValid && !!data.nombreSolicitante;
  }

  isUbicacionStepValid(): boolean {
    const data = this.formData();
    const domicilioValid = !!data.calle && !!data.numeroExterior && !!data.colonia;
    if (!domicilioValid) return false;
    if (!this.claveCatastralObligatoria()) return true;
    return !!data.claveCatastral;
  }

  isDocumentosOficialesStepValid(): boolean {
    const documentos = this.requisitosDocumentos().filter((r) => r.obligatorio);
    const docs = this.formData().documentosAdjuntos;
    return documentos.every((r) => {
      const doc = docs[r.id];
      return !!doc && !!doc.file && doc.id !== null;
    });
  }

  isPreRegistroStepValid(): boolean {
    const pagoReq = this.requisitoPago();
    if (!pagoReq || !pagoReq.obligatorio) return true;
    const doc = this.formData().documentosAdjuntos[pagoReq.id];
    return !!doc && !!doc.file && doc.id !== null;
  }

  verArchivo(file: File, documentId?: number | null): void {
    const prevUrl = this.selectedDocUrl();
    if (prevUrl) {
      URL.revokeObjectURL(prevUrl);
      this.selectedDocUrl.set(null);
    }

    if (documentId && file.size === 0) {
      this.selectedDocId.set(documentId);
      this.selectedDocUrl.set(null);
    } else {
      const url = URL.createObjectURL(file);
      this.selectedDocUrl.set(url);
      this.selectedDocId.set(null);
    }

    this.selectedDocNombre.set(file.name);
    this.mostrarVisor.set(true);
  }

  cerrarVisor(): void {
    const prevUrl = this.selectedDocUrl();
    if (prevUrl) {
      URL.revokeObjectURL(prevUrl);
      this.selectedDocUrl.set(null);
    }
    this.selectedDocId.set(null);
    this.selectedDocNombre.set(null);
    this.mostrarVisor.set(false);
  }

  isDocumentacionValid(): boolean {
    const tramite = this.selectedTramite();
    if (!tramite) return false;
    const obligatorios = tramite.requisitos.filter((r) => r.obligatorio);
    const docs = this.formData().documentosAdjuntos;
    return obligatorios.every((r) => {
      const doc = docs[r.id];
      return !!doc && !!doc.file && doc.id !== null;
    });
  }

  canProceedCurrentStep(): boolean {
    const current = this.currentPestana();
    if (!current) return false;

    if (current.id === 'seleccion') return this.selectedTramite() !== null;
    if (current.id === 'solicitante') return this.isSolicitanteStepValid();
    if (current.id === 'ubicacion') return this.isUbicacionStepValid();
    if (current.id === 'documentos') return this.isDocumentosOficialesStepValid();
    if (current.id === 'pre-registro') return this.isPreRegistroStepValid();
    return true;
  }

  enviarSolicitudTramite(): void {
    const tramite = this.selectedTramite();
    if (!tramite) return;

    if (!this.isSolicitanteStepValid() || !this.isUbicacionStepValid() || !this.isDocumentacionValid()) {
      this.submitError.set('Completa los campos obligatorios y adjunta la documentación requerida antes de enviar.');
      return;
    }

    this.submitError.set(null);
    this.isSubmitting.set(true);

    const data = this.formData();
    const esMoral = data.personalidad === 'moral';

    const documentos = Object.entries(data.documentosAdjuntos)
      .filter(([, doc]) => doc.id !== null && doc.id !== undefined)
      .map(([clave, doc]) => ({
        clave,
        documento_id: doc.id as number,
        firma_serial: null,
      }));

    const payload: SolicitudPayload = {
      tipo: 'tramite',
      personalidad_juridica: data.personalidad,
      rfc: data.rfc,
      correo_electronico: data.correo,
      nombre_proyecto: tramite.nombre,
      municipio_id: tramite.municipioId,
      sector_estrategico: false,
      tramite_datos: this.buildTramiteDatos(tramite, data),
      documentos,
    };

    if (esMoral) {
      payload.denominacion_razon_social = data.razonSocial;
      payload.nombre_representante = data.representanteLegal;
    } else {
      payload.nombre_completo = data.nombreSolicitante;
    }

    if (tramite.etapa === 'construccion' || tramite.etapa === 'operacion') {
      payload.etapa = tramite.etapa;
    }

    this.solicitudService
      .enviarSolicitudTramite(payload)
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: (res) => {
          this.isSubmitting.set(false);
          this.submitFolio.set(res.folio);
          this.submitSuccess.set(true);
        },
        error: (err) => {
          this.isSubmitting.set(false);
          this.submitError.set(extractErrorMessage(err));
        },
      });
  }

  private buildTramiteDatos(tramite: TramiteCatalogoItem, data: TramiteSolicitudData): TramiteDatosSolicitud {
    return {
      tramiteId: tramite.id,
      claveOficial: tramite.claveOficial,
      nombre: tramite.nombre,
      dependencia: tramite.dependencia,
      nivelGobierno: tramite.nivelGobierno,
      municipioNombre: tramite.municipioNombre,
      municipioId: tramite.municipioId,
      etapa: tramite.etapa,
      vigenciaDias: tramite.vigenciaDias,
      modalidad: tramite.modalidad,
      telefono: data.telefono ?? '',
      ubicacion: {
        calle: data.calle,
        numeroExterior: data.numeroExterior,
        numeroInterior: data.numeroInterior ?? '',
        colonia: data.colonia,
        codigoPostal: data.codigoPostal,
        claveCatastral: data.claveCatastral,
        superficieTotalM2: data.superficieTotalM2,
        superficieConstruidaM2: data.superficieConstruidaM2,
        latitud: data.latitud,
        longitud: data.longitud,
        altitud: data.altitud,
      },
      tecnica: {
        tipoTramiteEspecifico: data.tipoTramiteEspecifico ?? '',
        descripcionProyecto: data.descripcionProyecto ?? '',
        actividadPrincipal: data.actividadPrincipal ?? '',
        vidaUtilAnos: data.vidaUtilAnos ?? null,
        maquinariaEquipo: data.maquinariaEquipo ?? '',
        combustiblesUtilizados: data.combustiblesUtilizados ?? '',
        emisionesAtmosfera: data.emisionesAtmosfera ?? '',
        manejoResiduos: data.manejoResiduos ?? '',
        medidasMitigacion: data.medidasMitigacion ?? '',
        colindanciaNorte: data.colindanciaNorte ?? '',
        colindanciaSur: data.colindanciaSur ?? '',
        colindanciaEste: data.colindanciaEste ?? '',
        colindanciaOeste: data.colindanciaOeste ?? '',
        tipoGeneradorRme: data.tipoGeneradorRme ?? '',
      },
      requisitos: tramite.requisitos.map((r) => r.id),
    };
  }

  volverAlCatalogo(): void {
    void this.router.navigate(['/inversores/tramites']);
  }
}
